def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]

    def run_at_edge(col):
        vals = [grid[r][col] for r in range(h)]
        marked = [r for r, v in enumerate(vals) if v != bg]
        if not marked:
            return None
        color = vals[marked[0]]
        rows = [r for r in range(h) if vals[r] == color]
        return (min(rows), max(rows), color)

    left = run_at_edge(0)
    right = run_at_edge(w - 1)
    if left is None or right is None:
        return out
    l0, l1, lc = left
    r0, r1, rc = right
    if (l1 - l0) != (r1 - r0):
        return out

    for y in range(h):
        for x in range(1, w - 1):
            color = grid[y][x]
            if color == bg or color == lc or color == rc:
                continue
            if r0 <= y <= r1:
                k = y - r0
                paired_y = l0 + k
                out[y][x] = 4
                for xx in range(x + 1, w - 1):
                    out[y][xx] = color
                for xx in range(1, w - 1):
                    out[paired_y][xx] = color
            elif l0 <= y <= l1:
                k = y - l0
                paired_y = r0 + k
                out[y][x] = 4
                for xx in range(1, x):
                    out[y][xx] = color
                for xx in range(1, w - 1):
                    out[paired_y][xx] = color
    return out
